const results = [];

for (const item of items) {
  const d = item.json.body && typeof item.json.body === 'object' ? item.json.body : item.json;

  const eventid = d.eventid || '';
  const session = d.session || null;
  const src_ip = d.src_ip || null;
  const src_port = d.src_port || null;
  const username = d.username || null;
  const password = d.password || null;
  const input = d.input || null;
  const message = d.message || null;
  const timestamp = d.timestamp || new Date().toISOString();

  // GeoIP - best effort, don't block on failure
  let country = 'Desconocido';
  if (src_ip) {
    try {
      const resp = await fetch(`http://ip-api.com/json/${src_ip}?fields=country`, { signal: AbortSignal.timeout(2000) });
      const geo = await resp.json();
      if (geo.country) country = geo.country;
    } catch (e) {
      // GeoIP failed, keep default
    }
  }

  // Build safe SQL values
  const esc = (v) => v == null ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
  const inetVal = src_ip ? "'" + String(src_ip).replace(/'/g, "''") + "'::inet" : 'NULL';
  const portVal = src_port ? parseInt(src_port) : 'NULL';
  const tsVal = esc(timestamp);

  const sql = `INSERT INTO events (eventid, session, src_ip, src_port, username, password, input, message, timestamp, country) VALUES (${esc(eventid)}, ${esc(session)}, ${inetVal}, ${portVal}, ${esc(username)}, ${esc(password)}, ${esc(input)}, ${esc(message)}, ${tsVal}, ${esc(country)})`;

  results.push({ json: { sql, eventid, src_ip, session } });
}

return results;
